Method.Implementation:
	$$$TRACE("Inside "_..%ConfigName_" Method ProcessGetCPT4ModifierIDRequest")
	$$$TRACE("check "_pRequest.StandardModifiers)


	#dim tSC As %Status=$$$OK
	set tSC=..Adapter.SetAutoCommit(1) 		

	try{	
 	   set tSC=..Adapter.ExecuteQuery(.tResult,"select ID from CPT4_Modifier_DE where EntryCode ='"_pRequest.StandardModifiers_"'")
 	   //set tSC=..Adapter.ExecuteQuery(.tResult,"select ID from CPT4_Modifier_DE where EntryCode ='RENTAL'") 	
 	   $$$TRACE("  SUCCESS : "_tSC)		 	   	
	}CATCH err {		
	    $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	}	
	$$$TRACE("  STATUS : "_tSC)	
	set pResponse=##class(Ens.StringResponse).%New()

	$$$TRACE("check tResult "_tResult)
	If tResult.Next() {
     Set pResponse.StringValue = tResult.GetData(1)
     $$$TRACE("inside success")
   } Else {
     Set pResponse.StringValue = ""
     $$$TRACE("inside failure")
   }	

	$$$TRACE("  Query Result from CPT4_Modifier_DE : "_pResponse.StringValue)	
	quit tSC
